instance += u(1) + u(q['probeTurretTarget']) + bytes([1]) + u(0) + u(3)
classes = u(1) + instance + u(1) + u(0)
scripts = u(1) + u(2) + u(1) + u(q['BT3TurretTargetProbe']) + bytes([4]) + u(1) + u(0)


